<script>
window.addEventListener('load', function() {
  try {
    var banner = document.getElementById('promoBanner');
    if (!banner) return;
    var isClosed = localStorage.getItem('promoBannerClosed') === '1';
    if (isClosed) return;
    // Sayfa ve görseller tamamen yüklendikten sonra inline gizlemeyi kaldır
    banner.removeAttribute('aria-hidden');
    try { banner.style.removeProperty('display'); } catch(_) { banner.style.display = ''; }
    // İlk boyamayı sade tutmak için sınıfları gecikmeyle birlikte ekle
    setTimeout(function(){
      banner.classList.add('is-painted');
      banner.classList.add('is-ready');
    }, 800);
  } catch(e){}
});
</script>
