<script>
  function closeBanner() {
    var el = document.getElementById('promoBanner');
    if (el) el.style.display = 'none';
    try { localStorage.setItem('promoBannerClosedAt', String(Date.now())); } catch(e){}
  }
  (function(){
    try {
      var el = document.getElementById('promoBanner');
      if (!el) return;
      var KEY = 'promoBannerClosedAt';
      var reopenAfterMs = 2 * 24 * 60 * 60 * 1000;
      var lastClosed = null;
      try { lastClosed = localStorage.getItem(KEY); } catch(e){}
      var shouldShow = true;
      if (lastClosed) {
        var ts = parseInt(lastClosed, 10);
        if (!isNaN(ts)) shouldShow = (Date.now() - ts) >= reopenAfterMs;
      }
      if (shouldShow) {
        el.style.display = 'block';
        el.classList.add('is-ready');
        el.classList.add('is-painted');
        el.removeAttribute('aria-hidden');
        el.classList.add('is-visible');
      } else {
        el.style.display = 'none';
      }
    } catch(e){}
  })();

</script>

